export function effectRegion(W,H,x,y,radius,padding=64){const left=Math.max(0,Math.floor(x-radius-padding)),top=Math.max(0,Math.floor(y-radius-padding)),right=Math.min(W,Math.ceil(x+radius+padding)),bottom=Math.min(H,Math.ceil(y+radius+padding));return right>left&&bottom>top?{x:left,y:top,w:right-left,h:bottom-top}:null}
// Camera pixels never enter this layer. Only the cropped effect region is blurred.
export class Cinematic{
 constructor(){this.layer=document.createElement('canvas');this.blur=document.createElement('canvas');this.context=this.layer.getContext('2d');this.blurContext=this.blur.getContext('2d');this.width=0;this.height=0;this.stats={blurPixels:0,fullPixels:0}}
 begin(W,H,ratio=1.25){const width=Math.max(1,Math.round(W*ratio)),height=Math.max(1,Math.round(H*ratio));if(this.layer.width!==width||this.layer.height!==height){this.layer.width=width;this.layer.height=height;this.blur.width=Math.max(1,Math.round(W*.45));this.blur.height=Math.max(1,Math.round(H*.45))}this.context.setTransform(ratio,0,0,ratio,0,0);this.context.clearRect(0,0,W,H);this.width=W;this.height=H;return this.context}
 composite(target,source=this.layer,{base=true,strength=1,region}={}){const W=this.width,H=this.height;if(!W||!H)return;target.save();try{if(base)target.drawImage(source,0,0,W,H);const r=region===undefined?{x:0,y:0,w:W,h:H}:region;if(!r){this.stats.blurPixels=0;return}const bw=Math.max(1,Math.round(r.w*.45)),bh=Math.max(1,Math.round(r.h*.45)),b=this.blurContext;b.clearRect(0,0,this.blur.width,this.blur.height);b.drawImage(source,r.x*source.width/W,r.y*source.height/H,r.w*source.width/W,r.h*source.height/H,0,0,bw,bh);this.stats={blurPixels:bw*bh,fullPixels:this.blur.width*this.blur.height};target.globalCompositeOperation='lighter';target.globalAlpha=.72*strength;target.filter='blur(13px)';target.drawImage(this.blur,0,0,bw,bh,r.x,r.y,r.w,r.h);target.globalAlpha=.5*strength;target.filter='blur(3px)';target.drawImage(this.blur,0,0,bw,bh,r.x,r.y,r.w,r.h)}finally{target.restore()}}
}
